                self.peer.sendCallResolvedGeneratedWithOptions(.{ .exported = .{ .id = self.cap_id } }, interface_id, Fast.ordinal, ctx, Fast.callBuild, Fast.callReturn, options)
            else
                self.peer.sendCallGeneratedWithOptions(self.cap_id, interface_id, Fast.ordinal, ctx, Fast.callBuild, Fast.callReturn, options);
            const question_id = sent catch |err| {
                if (!settled) self.peer.allocator.destroy(ctx);
                return err;
            };
            if (settled) return question_id;
            ctx.settled_flag = null;
            self.peer.setQuestionDeinitCtx(question_id, Fast.CallContext.deinitCtx);
            return question_id;
        }

        pub fn callGetSub(self: Client, user_ctx: *anyopaque, build: ?GetSub.BuildFn, on_return: GetSub.Callback) !u32 {
            return self.callGetSubWithOptions(user_ctx, build, on_return, .{});
        }

        pub fn callGetSubWithOptions(self: Client, user_ctx: *anyopaque, build: ?GetSub.BuildFn, on_return: GetSub.Callback, options: rpc.peer.CallOptions) !u32 {
            const ctx = try self.peer.allocator.create(GetSub.CallContext);
            var settled = false;
            ctx.* = .{ .user_ctx = user_ctx, .build = build, .callback = on_return, .settled_flag = &settled };
            const sent = if (self.origin == .exported)
                self.peer.sendCallResolvedGeneratedWithOptions(.{ .exported = .{ .id = self.cap_id } }, interface_id, GetSub.ordinal, ctx, GetSub.callBuild, GetSub.callReturn, options)
            else
                self.peer.sendCallGeneratedWithOptions(self.cap_id, interface_id, GetSub.ordinal, ctx, GetSub.callBuild, GetSub.callReturn, options);
            const question_id = sent catch |err| {
                if (!settled) self.peer.allocator.destroy(ctx);
                return err;
