        pub fn callGetSubPipelined(self: Client, user_ctx: *anyopaque, build: ?GetSub.BuildFn, on_return: GetSub.Callback) !GetSubPipeline {
            return self.callGetSubPipelinedWithOptions(user_ctx, build, on_return, .{});
