        pub fn callFastWithOptions(self: PipelinedClient, user_ctx: *anyopaque, build: ?Fast.BuildFn, on_return: Fast.Callback, options: rpc.peer.CallOptions) !u32 {
            if (self.pointer_count >= 64) return error.PipelineDepthLimit;
            var ops: [64]rpc.wire.protocol.PromisedAnswerOp = undefined;
            for (self.pointer_indexes[0..self.pointer_count], 0..) |index, i| ops[i] = .{ .tag = .getPointerField, .pointer_index = index };
            ops[self.pointer_count] = .{ .tag = .getPointerField, .pointer_index = self.pointer_index };
            const ctx = try self.peer.allocator.create(Fast.CallContext);
            var settled = false;
            ctx.* = .{ .user_ctx = user_ctx, .build = build, .callback = on_return, .settled_flag = &settled };
            const question_id = self.peer.sendCallPromisedWithOpsGeneratedWithOptions(self.question_id, ops[0 .. @as(usize, self.pointer_count) + 1], interface_id, Fast.ordinal, ctx, Fast.callBuild, Fast.callReturn, options) catch |err| {
                if (!settled) self.peer.allocator.destroy(ctx);
                return err;
            };
            if (settled) return question_id;
            ctx.settled_flag = null;
            self.peer.setQuestionDeinitCtx(question_id, Fast.CallContext.deinitCtx);
            return question_id;
        }

        pub fn callGetSub(self: PipelinedClient, user_ctx: *anyopaque, build: ?GetSub.BuildFn, on_return: GetSub.Callback) !u32 {
            return self.callGetSubWithOptions(user_ctx, build, on_return, .{});
        }

        pub fn callGetSubWithOptions(self: PipelinedClient, user_ctx: *anyopaque, build: ?GetSub.BuildFn, on_return: GetSub.Callback, options: rpc.peer.CallOptions) !u32 {
            if (self.pointer_count >= 64) return error.PipelineDepthLimit;
            var ops: [64]rpc.wire.protocol.PromisedAnswerOp = undefined;
            for (self.pointer_indexes[0..self.pointer_count], 0..) |index, i| ops[i] = .{ .tag = .getPointerField, .pointer_index = index };
            ops[self.pointer_count] = .{ .tag = .getPointerField, .pointer_index = self.pointer_index };
            const ctx = try self.peer.allocator.create(GetSub.CallContext);
            var settled = false;
            ctx.* = .{ .user_ctx = user_ctx, .build = build, .callback = on_return, .settled_flag = &settled };
            const question_id = self.peer.sendCallPromisedWithOpsGeneratedWithOptions(self.question_id, ops[0 .. @as(usize, self.pointer_count) + 1], interface_id, GetSub.ordinal, ctx, GetSub.callBuild, GetSub.callReturn, options) catch |err| {
                if (!settled) self.peer.allocator.destroy(ctx);
